(*
【需求原文】
In an industrial water supply system, there are 5 pumps, each of which can be controlled independently. The system needs to support both manual and automatic operating modes.
Based on the value of the mode variable, switch to the corresponding operating mode.
In manual mode, control the start and stop of the selected pump based on the value of pumpGroup[1..5].selection.
In automatic mode, compare the priority of each pump, and automatically select the 3 pumps with higher priority for water supply according to the method of three in use and two on standby.

P07；每次调用为一个20 ms扫描周期。
priority、selection、RunComd保持为ST_Pump字段，与声明骨架一致。
仅写pumpGroup[i].RunComd，不修改priority或selection。

规约冲突报告（保留待审，不声称全部规约已满足）：
1. K2无条件要求自动模式恰有3台运行，但初态、C10和stop优先
   均要求某些周期全部停止，这些要求无法无条件同时成立。
2. C4约束的是只读输入start、stop，功能块不能保证外部请求互斥。
   同时有效时仍按K4执行停止。
3. 若C6逐泵解释为运行保持至stop，则与手动取消选择、
   模式切换以及自动优先级变化时重新选泵可能冲突。
   若RunComd指单独输出，则与给定骨架仅含结构字段的接口不一致。

以下实现执行明确的停止优先、启动许可保持、模式选择和确定性排名；
C10的[0,1]按扫描序号0和1两个周期禁止启动。
start按电平处理；启动许可保持至stop。
许可有效期间，每周期按当前模式和输入重新计算泵命令。
因此不宣称满足上述存在冲突的无条件K2或逐泵C6。
未提供编译或逐周期测试验证证据。
*)

TYPE ST_Pump :
STRUCT
    priority : INT;
    selection : BOOL;
    RunComd : BOOL;
END_STRUCT
END_TYPE

FUNCTION_BLOCK FB_P07
VAR_INPUT
    mode : BOOL;
    start : BOOL;
    stop : BOOL;
END_VAR
VAR_IN_OUT
    pumpGroup : ARRAY[1..5] OF ST_Pump;
END_VAR
VAR
    startupScans : INT := 0;
    runEnabled : BOOL := FALSE;
    i : INT;
    j : INT;
    higherCount : INT;
END_VAR

(* 首两个扫描周期强制关闭全部命令，不接受启动请求。 *)
IF startupScans < 2 THEN
    runEnabled := FALSE;
    startupScans := startupScans + 1;

    FOR i := 1 TO 5 DO
        pumpGroup[i].RunComd := FALSE;
    END_FOR;

ELSE
    (* 停止具有最高优先级，包括start与stop同时有效的情况。 *)
    IF stop THEN
        runEnabled := FALSE;
    ELSIF start THEN
        runEnabled := TRUE;
    END_IF;

    IF NOT runEnabled THEN
        FOR i := 1 TO 5 DO
            pumpGroup[i].RunComd := FALSE;
        END_FOR;

    ELSIF NOT mode THEN
        (* 手动模式：启动许可有效时按各泵选择状态控制。 *)
        FOR i := 1 TO 5 DO
            pumpGroup[i].RunComd := pumpGroup[i].selection;
        END_FOR;

    ELSE
        (*
        自动模式：统计排在本泵之前的泵数。
        使用比较而非优先级相减，避免INT极值溢出。
        优先级降序、泵号升序形成唯一顺序；前三名运行。
        *)
        FOR i := 1 TO 5 DO
            higherCount := 0;

            FOR j := 1 TO 5 DO
                IF pumpGroup[j].priority > pumpGroup[i].priority THEN
                    higherCount := higherCount + 1;
                ELSIF pumpGroup[j].priority = pumpGroup[i].priority THEN
                    IF j < i THEN
                        higherCount := higherCount + 1;
                    END_IF;
                END_IF;
            END_FOR;

            pumpGroup[i].RunComd := higherCount < 3;
        END_FOR;
    END_IF;
END_IF;

END_FUNCTION_BLOCK
